steps.run:
set -euo pipefail

service_url="$(gcloud run services describe "$GCP_CLOUD_RUN_SERVICE" \
  --region "$GCP_REGION" \
  --project "$GCP_PROJECT_ID" \
  --format='value(status.url)')"

SERVICE_URL="$service_url" node --input-type=module - <<'NODE'
const value = process.env.SERVICE_URL ?? '';
let parsed;
try {
  parsed = new URL(value);
} catch {
  console.error('Cloud Run status.url is not a valid URL.');
  process.exit(1);
}

if (
  parsed.protocol !== 'https:' ||
  parsed.username !== '' ||
  parsed.password !== '' ||
  parsed.pathname !== '/' ||
  parsed.search !== '' ||
  parsed.hash !== '' ||
  parsed.origin !== value
) {
  console.error('Cloud Run status.url must be an exact HTTPS origin with no path, query, fragment, or credentials.');
  process.exit(1);
}
NODE

echo "service_url=$service_url" >> "$GITHUB_OUTPUT"
printf '%s\n' "$service_url" | tee "${RUNNER_TEMP}/production-cloud-run-origin.txt"
printf 'Authoritative Cloud Run origin: `%s`\n' "$service_url" >> "$GITHUB_STEP_SUMMARY"
